import React, { useState, useEffect } from "react";
import {
  BrowserRouter as Router,
  Routes,
  Route,
  Link,
  useNavigate,
} from "react-router-dom";
import axios from "axios";
import Plot from "react-plotly.js";
import "./App.css";

const API_BASE_URL = "http://localhost:5000";

/* -----------------------
   Navigation (top bar)
   ----------------------- */
function Navigation() {
  const [stats, setStats] = useState(null);

  useEffect(() => {
    let mounted = true;
    const fetchStats = async () => {
      try {
        const res = await axios.get(`${API_BASE_URL}/stats`);
        if (mounted) setStats(res.data);
      } catch (e) {
        // silently ignore — nav is non-critical
      }
    };
    fetchStats();
    return () => (mounted = false);
  }, []);

  return (
    <nav className="navbar" role="navigation" aria-label="Main navigation">
      <div className="nav-brand">
        <Link to="/" aria-label="Go to SonarSense home">
          <span className="logo" aria-hidden>
            🌊
          </span>
          <span className="brand-name">SonarSense</span>
        </Link>
      </div>

      <div className="nav-links">
        <Link to="/" className="nav-link">
          Analyze
        </Link>
        <Link to="/history" className="nav-link">
          History
        </Link>
        <Link to="/admin" className="nav-link">
          Admin
        </Link>

        {stats && (
          <div className="nav-stat" aria-live="polite">
            <span style={{ opacity: 0.9 }}>Total:</span>
            <strong style={{ marginLeft: 8 }}>{stats.total_predictions}</strong>
          </div>
        )}
      </div>
    </nav>
  );
}

/* -----------------------
   Analyze Page
   ----------------------- */
function AnalyzePage() {
  const [file, setFile] = useState(null);
  const [prediction, setPrediction] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const resetState = () => {
    setError(null);
    setPrediction(null);
  };

  const handleFileChange = (e) => {
    resetState();
    const f = e.target.files?.[0] ?? null;
    setFile(f);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    resetState();

    if (!file) {
      setError("Please choose an audio file to analyze.");
      return;
    }

    setLoading(true);
    try {
      const fd = new FormData();
      fd.append("file", file);

      const res = await axios.post(`${API_BASE_URL}/predict`, fd, {
        headers: { "Content-Type": "multipart/form-data" },
        timeout: 120000,
      });

      setPrediction(res.data);
    } catch (err) {
      console.error(err);
      setError(
        err.response?.data?.error ||
          "Could not analyze the file. Please try another clip or check the backend."
      );
    } finally {
      setLoading(false);
    }
  };

  const downloadReport = async (resultId) => {
    try {
      const res = await axios.get(`${API_BASE_URL}/report/${resultId}`, {
        responseType: "blob",
      });
      const url = window.URL.createObjectURL(new Blob([res.data]));
      const a = document.createElement("a");
      a.href = url;
      a.download = `sonar_report_${resultId}.pdf`;
      document.body.appendChild(a);
      a.click();
      a.remove();
      window.URL.revokeObjectURL(url);
    } catch (err) {
      console.error(err);
      alert("Failed to download report.");
    }
  };

  const confidenceColor = (c) => {
    if (c > 0.8) return "#10b981";
    if (c > 0.6) return "#f59e0b";
    return "#ef4444";
  };

  const confidenceLabel = (c) => {
    if (c > 0.8) return "High confidence";
    if (c > 0.6) return "Medium confidence";
    return "Low confidence";
  };

  return (
    <div className="analyze-page" aria-live="polite">
      <div className="page-header">
        <div>
          <h1>🎯 SonarSense — analyze a signal</h1>
          <p>
            Upload a sonar clip (.wav / .mp3 / .flac). SonarSense will listen and
            suggest what it might be — torpedo, submarine, fish, or rock.
          </p>
        </div>
      </div>

      <section className="upload-section" aria-labelledby="upload-heading">
        <form onSubmit={handleSubmit} className="upload-form">
          <label htmlFor="file-input" className="file-label" title="Choose audio">
            <input
              id="file-input"
              className="file-input"
              type="file"
              accept=".wav,.mp3,.flac"
              onChange={handleFileChange}
              aria-label="Choose sonar audio file"
            />
            <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
              <div style={{ fontSize: 22 }}>📁</div>
              <div>
                <div style={{ fontWeight: 700 }}>
                  {file ? file.name : "Choose a sonar audio file"}
                </div>
                <div style={{ color: "#6b7280", fontSize: 13 }}>
                  Accepts WAV, MP3, FLAC — try a short clip (1–10s)
                </div>
              </div>
            </div>
          </label>

          <button
            type="submit"
            className="analyze-btn"
            disabled={loading || !file}
            aria-disabled={loading || !file}
          >
            {loading ? "Analyzing..." : "Analyze Signal"}
          </button>
        </form>

        {error && (
          <div className="error-message" role="alert" style={{ marginTop: 12 }}>
            ⚠️ {error}
          </div>
        )}
      </section>

      {prediction && (
        <section className="results-container" aria-live="polite">
          <div className="result-card main-result" role="region" aria-label="Prediction">
            <div className="result-header">
              <div>
                <h2 style={{ margin: 0 }}>Classification Result</h2>
                <div style={{ marginTop: 6, color: "#6b7280" }}>
                  ID: #{prediction.result_id}
                </div>
              </div>
            </div>

            <div className="prediction-display">
              <div className="prediction-icon" aria-hidden>
                {prediction.prediction === "Torpedo" && "🚀"}
                {prediction.prediction === "Submarine" && "🚢"}
                {prediction.prediction === "Fish" && "🐟"}
                {prediction.prediction === "Rock" && "🪨"}
                {prediction.prediction === "Unknown" && "❓"}
              </div>

              <div style={{ flex: 1 }}>
                <div className="prediction-label">{prediction.prediction}</div>

                <div className="confidence-bar-container" aria-hidden>
                  <div
                    className="confidence-bar"
                    style={{
                      width: `${prediction.confidence * 100}%`,
                      background: confidenceColor(prediction.confidence),
                    }}
                  />
                </div>

                <div className="confidence-info" style={{ marginTop: 6 }}>
                  <div style={{ fontWeight: 700 }}>
                    {(prediction.confidence * 100).toFixed(2)}%
                  </div>
                  <div style={{ color: confidenceColor(prediction.confidence) }}>
                    {confidenceLabel(prediction.confidence)}
                  </div>
                </div>
              </div>
            </div>

            <div className="probabilities-grid" aria-hidden>
              {Object.entries(prediction.probabilities).map(([label, prob]) => (
                <div key={label} className="probability-item">
                  <div className="prob-label">{label}</div>
                  <div className="prob-bar-bg">
                    <div
                      className="prob-bar"
                      style={{
                        width: `${prob * 100}%`,
                        background: "#3b82f6",
                      }}
                    />
                  </div>
                  <div style={{ width: 60, textAlign: "right", fontWeight: 700 }}>
                    {(prob * 100).toFixed(1)}%
                  </div>
                </div>
              ))}
            </div>

            <div className="result-actions">
              <div style={{ display: "flex", gap: 12 }}>
                <button
                  onClick={() => downloadReport(prediction.result_id)}
                  className="download-btn"
                >
                  📄 Download Report
                </button>
              </div>

              <div className="timestamp">
                Analyzed: {new Date(prediction.timestamp).toLocaleString()}
              </div>
            </div>
          </div>

          {/* Waveform */}
          {prediction.waveform_data?.time && (
            <div className="result-card" role="region" aria-label="Waveform">
              <h3>Signal Waveform</h3>
              <Plot
                data={[
                  {
                    x: prediction.waveform_data.time,
                    y: prediction.waveform_data.amplitude,
                    type: "scatter",
                    mode: "lines",
                    name: "Amplitude",
                  },
                ]}
                layout={{
                  autosize: true,
                  margin: { l: 50, r: 20, t: 40, b: 50 },
                  xaxis: { title: "Time (s)" },
                  yaxis: { title: "Amplitude" },
                }}
                style={{ width: "100%", height: 340 }}
                config={{ responsive: true, displayModeBar: false }}
              />
            </div>
          )}

          {/* Frequency */}
          {prediction.frequency_data?.frequency && (
            <div className="result-card" role="region" aria-label="Frequency spectrum">
              <h3>Frequency Spectrum</h3>
              <Plot
                data={[
                  {
                    x: prediction.frequency_data.frequency,
                    y: prediction.frequency_data.magnitude,
                    type: "scatter",
                    mode: "lines",
                    fill: "tozeroy",
                    name: "Magnitude",
                  },
                ]}
                layout={{
                  autosize: true,
                  margin: { l: 50, r: 20, t: 40, b: 50 },
                  xaxis: { title: "Frequency (Hz)" },
                  yaxis: { title: "Magnitude" },
                }}
                style={{ width: "100%", height: 340 }}
                config={{ responsive: true, displayModeBar: false }}
              />
            </div>
          )}
        </section>
      )}
    </div>
  );
}

/* -----------------------
   History Page
   ----------------------- */
function HistoryPage() {
  const [history, setHistory] = useState([]);
  const [loading, setLoading] = useState(true);

  const fetchHistory = async () => {
    setLoading(true);
    try {
      const res = await axios.get(`${API_BASE_URL}/history?limit=50`);
      setHistory(res.data.history || []);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchHistory();
  }, []);

  const downloadReport = async (id) => {
    try {
      const res = await axios.get(`${API_BASE_URL}/report/${id}`, {
        responseType: "blob",
      });
      const url = window.URL.createObjectURL(new Blob([res.data]));
      const a = document.createElement("a");
      a.href = url;
      a.download = `sonar_report_${id}.pdf`;
      document.body.appendChild(a);
      a.click();
      a.remove();
      window.URL.revokeObjectURL(url);
    } catch (err) {
      console.error(err);
      alert("Failed to download report.");
    }
  };

  if (loading) {
    return (
      <div className="main-content">
        <div className="loading-container">
          <div className="spinner large" />
          <div style={{ color: "#6b7280" }}>Loading prediction history...</div>
        </div>
      </div>
    );
  }

  return (
    <div className="main-content">
      <div className="page-header">
        <div>
          <h1>📊 Prediction History</h1>
          <p style={{ color: "#6b7280" }}>Recent analyses and downloadable reports.</p>
        </div>
      </div>

      <div className="history-table-container">
        <table className="history-table" role="table" aria-label="Prediction history">
          <thead>
            <tr>
              <th>ID</th>
              <th>Detection</th>
              <th>Confidence</th>
              <th>Timestamp</th>
              <th>Actions</th>
            </tr>
          </thead>

          <tbody>
            {history.length === 0 ? (
              <tr>
                <td colSpan="5" style={{ padding: 24, textAlign: "center", color: "#6b7280" }}>
                  No predictions yet — try analyzing a signal.
                </td>
              </tr>
            ) : (
              history.map((h) => (
                <tr key={h.id}>
                  <td>#{h.id}</td>
                  <td>
                    <span className="prediction-badge">{h.prediction}</span>
                  </td>
                  <td>
                    <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                      <div
                        style={{
                          width: 10,
                          height: 10,
                          borderRadius: 999,
                          background:
                            h.confidence > 0.8 ? "#10b981" : h.confidence > 0.6 ? "#f59e0b" : "#ef4444",
                        }}
                      />
                      <div style={{ fontWeight: 700 }}>{(h.confidence * 100).toFixed(1)}%</div>
                    </div>
                  </td>
                  <td>{new Date(h.created_at).toLocaleString()}</td>
                  <td>
                    <button className="download-btn" onClick={() => downloadReport(h.id)}>
                      📄
                    </button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

/* -----------------------
   Admin Page
   ----------------------- */
function AdminPage() {
  const [modelInfo, setModelInfo] = useState(null);
  const [training, setTraining] = useState(false);
  const [trainResult, setTrainResult] = useState(null);
  const [error, setError] = useState(null);
  const [token, setToken] = useState("admin123");

  const fetchModelInfo = async () => {
    try {
      const res = await axios.get(`${API_BASE_URL}/model/info`);
      setModelInfo(res.data);
    } catch (err) {
      setModelInfo(null);
    }
  };

  useEffect(() => {
    fetchModelInfo();
  }, []);

  const retrain = async () => {
    if (!window.confirm("Retrain model? This may take a while.")) return;
    setTraining(true);
    setTrainResult(null);
    setError(null);

    try {
      const res = await axios.post(`${API_BASE_URL}/train`, {}, { headers: { "X-Admin-Token": token } });
      setTrainResult(res.data);
      await fetchModelInfo();
    } catch (err) {
      console.error(err);
      setError(err.response?.data?.error || "Training failed.");
    } finally {
      setTraining(false);
    }
  };

  return (
    <div className="main-content">
      <div className="page-header">
        <div>
          <h1>⚙️ Admin</h1>
          <p style={{ color: "#6b7280" }}>Model controls and system information.</p>
        </div>
      </div>

      <div className="admin-grid">
        <div className="admin-card">
          <h3>Model Info</h3>
          {!modelInfo ? (
            <div style={{ color: "#6b7280" }}>Model info not available.</div>
          ) : (
            <div className="info-list">
              <div>
                <strong>Type:</strong> {modelInfo.model_type}
              </div>
              <div>
                <strong>Features:</strong> {modelInfo.n_features}
              </div>
              <div>
                <strong>Classes:</strong> {modelInfo.n_classes}
              </div>
              <div style={{ marginTop: 8 }}>
                {modelInfo.classes?.map((c) => (
                  <span key={c} style={{ marginRight: 8 }} className="prediction-badge">
                    {c}
                  </span>
                ))}
              </div>
            </div>
          )}
        </div>

        <div className="admin-card">
          <h3>Retrain Model</h3>
          <div style={{ marginTop: 8 }}>
            <label style={{ display: "block", color: "#6b7280", marginBottom: 6 }}>Admin token</label>
            <input
              value={token}
              onChange={(e) => setToken(e.target.value)}
              style={{ padding: 10, width: "100%", borderRadius: 10, border: "1px solid var(--border)" }}
            />
          </div>

          <div style={{ marginTop: 12, display: "flex", gap: 12 }}>
            <button className="analyze-btn" onClick={retrain} disabled={training}>
              {training ? "Training…" : "Retrain Model"}
            </button>
            {trainResult && (
              <div style={{ alignSelf: "center" }}>
                <div style={{ fontWeight: 700 }}>{(trainResult.accuracy * 100).toFixed(2)}%</div>
                <div style={{ color: "#6b7280", fontSize: 13 }}>accuracy</div>
              </div>
            )}
          </div>

          {error && <div className="error-message" style={{ marginTop: 12 }}>{error}</div>}
        </div>

        <div className="admin-card">
          <h3>System</h3>
          <div style={{ marginTop: 8 }}>
            <div><strong>API:</strong> {API_BASE_URL}</div>
            <div style={{ marginTop: 6 }}><strong>Version:</strong> 1.0.0</div>
            <div style={{ marginTop: 6 }}><strong>Status:</strong> <span style={{ color: "#10b981", fontWeight: 700 }}>Online</span></div>
          </div>
        </div>
      </div>
    </div>
  );
}

/* -----------------------
   App (routes)
   ----------------------- */
function App() {
  return (
    <Router>
      <div className="App">
        <Navigation />
        <main className="main-content">
          <Routes>
            <Route path="/" element={<AnalyzePage />} />
            <Route path="/history" element={<HistoryPage />} />
            <Route path="/admin" element={<AdminPage />} />
          </Routes>
        </main>
        <footer className="app-footer">
          <div>SonarSense © {new Date().getFullYear()} — AI-powered sonar classification</div>
          <div style={{ color: "#6b7280", fontSize: 13 }}>Built with Python, Flask and React</div>
        </footer>
      </div>
    </Router>
  );
}

export default App;
